package mrpapermoon.whisper.mesh.diimport android.content.Contextimport androidx.room.Roomimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.SupervisorJobimport mrpapermoon.whisper.entity.Userimport mrpapermoon.whisper.mesh.MeshNetworkManagerimport mrpapermoon.whisper.mesh.MeshNetworkManagerImplimport mrpapermoon.whisper.mesh.db.NetworkMessageDaoimport mrpapermoon.whisper.mesh.db.RumorDatabaseimport mrpapermoon.whisper.mesh.db.WhispererDaoimport mrpapermoon.whisper.service.NearbyConnectionsAdapterimport javax.inject.Singleton@Module@InstallIn(SingletonComponent::class)internal interface MeshModule {	@Provides	@Singleton	fun provideRumorDatabase(		@ApplicationContext context: Context	): RumorDatabase {		return Room.databaseBuilder(			context,			RumorDatabase::class.java,			"mesh_database"		).build()	}	@Provides	@Singleton	fun provideMeshNetworkManager(		@ApplicationContext context: Context,		rumorDatabase: RumorDatabase,		user: User,	): MeshNetworkManager {		return MeshNetworkManagerImpl(			context = context,			database = rumorDatabase,			uuid = user.id,			cipher = user.cipher,			userName = user.name,		)	}	@Provides	fun provideNetworkMessageDao(database: RumorDatabase): NetworkMessageDao = database.networkMessageDao()	@Provides	fun provideWhispererDao(database: RumorDatabase): WhispererDao = database.whispererDao()	@Provides	@Singleton	fun provideNearbyConnectionsAdapter(		@ApplicationContext context: Context,		user: User,	): NearbyConnectionsAdapter {		val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())		return NearbyConnectionsAdapter.getConnectionsAdapter(context, scope, user.id)	}}